WITH base AS (SELECT id, customer_id, browser, started_at, LENGTH(country) AS country_length, SUBSTRING(browser, 1, 4) AS browser_prefix FROM sessions WHERE started_at >= TO_DATE('2023-05-03') AND browser IS NOT NULL) SELECT id, customer_id, MAX(country_length) OVER (PARTITION BY customer_id ORDER BY CAST(started_at AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS country_length_max_90d, RANK() OVER (PARTITION BY browser ORDER BY country_length DESC) AS country_length_rank FROM base WHERE TO_DATE(started_at) < '2025-06-16';
